SELECT

FROM ACCOUNT_REPORT
WHERE
LOGIC_DEL = 0

    AND REMARK = #{dto.remark}


    AND USER_ID = #{dto.userId}


    AND BUDGET_ID = #{dto.budgetId}


    AND STRATEGY_ID = #{dto.strategyId}


    AND TITLE = #{dto.title}


    AND BUDGET_TYPE = #{dto.budgetType}


    AND BUDGET_AMOUNT = #{dto.budgetAmount}


    AND OUTLAY = #{dto.outlay}


    AND INCOME_AMOUNT = #{dto.incomeAmount}


    AND BILLING_TIME = #{dto.billingTime}


    AND BILLING_TIME_FROM = #{dto.billingTimeFrom}


    AND BILLING_TIME_TO = #{dto.billingTimeTo}


    AND RECALCULATE_FLAG = #{dto.recalculateFlag}

ORDER BY create_time DESC

SELECT

FROM ACCOUNT_REPORT,ACCOUNT_REPORT_STRATEGY
WHERE LOGIC_DEL = 0

    AND REMARK = #{dto.remark}


    AND USER_ID = #{dto.userId}


    AND BUDGET_ID = #{dto.budgetId}


    AND STRATEGY_ID = #{dto.strategyId}


    AND TITLE = #{dto.title}


    AND BUDGET_TYPE = #{dto.budgetType}


    AND BUDGET_AMOUNT = #{dto.budgetAmount}


    AND OUTLAY = #{dto.outlay}


    AND INCOME_AMOUNT = #{dto.incomeAmount}


    AND BILLING_TIME = #{dto.billingTime}


    AND BILLING_TIME_FROM = #{dto.billingTimeFrom}


    AND BILLING_TIME_TO = #{dto.billingTimeTo}


    AND RECALCULATE_FLAG = #{dto.recalculateFlag}

ORDER BY MODIFY_TIME DESC
